void sig_handler(int sig) {
    // sig identifies the signal received
    printf("Signal %d received.\n", sig);
    // Execute cleanup or logging...
    _exit(EXIT_SUCCESS); // Terminate gracefully
}

// Installation: Register custom handler for Ctrl+C
signal(SIGINT, sig_handler);

// Standard Uses (Constants):

// 1. Reset to default behavior
signal(SIGTERM, SIG_DFL);

// 2. Ignore the signal
signal(SIGTSTP, SIG_IGN);

// Prototype:
// sighandler_t signal(int signum, sighandler_t handler);
// sighandler_t is often void (*)(int)
